import React from 'react';
import { Link } from 'react-router-dom';

function Home() {
  return (
    <div className="home-page">
      <h1>Welcome to the AI Resume Builder</h1>
      <p>Create a stunning, professional resume in minutes with the power of AI. Choose a template, fill in your details, and download your resume instantly!</p>
      <Link to="/templates" className="get-started-btn">Get Started</Link>
    </div>
  );
}

export default Home;
